#
# webclient_assets.py
#
# ## TILAU ## PWA install assets for the mobile client (Phase 4c).
# GENERATED by tools/shell/gen_app_icons.py from includes/Icons/tilauscope-mark.svg.
# The coffee-bean mark recoloured cream on a Catppuccin #1E1E2E tile,
# base64-embedded so it is self-contained/cross-platform (no runtime
# SVG rasteriser). Served by TilauWebControl at /icon-<size>.png and
# /manifest.webmanifest; iOS "Add to Home Screen" opens it standalone.
#
import base64

ICON_180_B64 = ""
ICON_192_B64 = ""
ICON_512_B64 = ""

def icon_png(size: int) -> bytes:
    return base64.b64decode({180: ICON_180_B64, 192: ICON_192_B64,
                             512: ICON_512_B64}.get(size, ICON_512_B64))

MANIFEST = {
    "name": "TilauScope",
    "short_name": "TilauScope",
    "start_url": "/",
    "scope": "/",
    "display": "standalone",
    "orientation": "any",
    "background_color": "#1E1E2E",
    "theme_color": "#1E1E2E",
    "icons": [
        {"src": "/icon-192.png", "sizes": "192x192", "type": "image/png"},
        {"src": "/icon-512.png", "sizes": "512x512", "type": "image/png",
         "purpose": "any maskable"},
    ],
}
